// Glance — the workspace project-network graph model (#2206, epic #2205). Pure (no React/Tauri): turns
// a raw {nodes, edges} project graph into a laid-out, cycle-aware model the canvas renders. Ported from
// the user's "Relationship graph interaction spec" (Glance Network) buildModel — generalized to take
// the graph as input (the real project list feeds it via glanceData.ts) instead of hardcoded data.
//
// The graph is a DEPENDENCY DAG: `from depends on to`. Layers flow left→right by dependency depth
// (a foundational project with no deps sits at layer 0). Mutual pairs (a↔b) are CYCLES — surfaced as
// coordination hazards. This is the DAG/graph layout in the "layout follows data structure" sense
// (#2204): the same layered algorithm the Org designer uses, on a different domain.
import { neighborSpotlight } from "@/shared/lib/graph/spotlight";
import { mutualPairs } from "@/shared/lib/graph/cycles";
import { layerDag } from "@/shared/lib/graph/layers";
import { orderLayers } from "@/shared/lib/graph/order";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import type { NodeGraph } from "@/shared/lib/graph/nodeUrn";
// Cross-feature TYPE only, via the barrel (#1309 boundary) — the project's application architecture
// (#3786/#3802), surfaced on each project node as the contract endpoint-type discriminator. `import type`
// is erased at build, so this adds no runtime edge to the planner (no cycle, HMR-safe).
import type { AppType } from "@/features/planner";

export type GRole = "infra" | "service" | "data" | "client";
/** Axis 1 — HEALTH (#2541): the top-left dot colour + the attention/propagation signal. An escalation
 *  ladder that rolls UP the dependency chain (a node shows the worst of itself + everything it depends
 *  on). `healthy` never propagates — only `warning`/`error` do. Sourced from the worst unresolved
 *  `bsc errors` FaultLevel; this REPLACES the old separate fault badge. `off` (#3239) is the one MANUAL
 *  value — the user has deactivated the node from its details pane; it renders greyed, wins over the live
 *  status ("if it's not idle then it should be off"), and — being rank 0 — never propagates and never
 *  inherits a downstream error (see {@link rollUpHealth}).
 *
 *  `modifying` (#4052) is the rung that was missing: `healthy` says nothing is WRONG and `complete` says
 *  the work is DONE, but neither said the work is IN FLIGHT. It replaces the LIFECYCLE category axis,
 *  which had degenerated to one boolean — across the local hubs NO project carried a discovered
 *  lifecycle, so `resolveProjectCategory` always fell through to `isDraft ? greenfield : maintain`, and
 *  six legend rows rendered two values. (The same degeneration removed the blueprint category in #3785.)
 *  Now L0 projects read on the SAME two axes as fleet nodes instead of a third, mostly-dead one. */
export type GHealth = "healthy" | "warning" | "error" | "off" | "complete" | "modifying";
/**
 * Does this node carry the BUILDING pulse (#4015)?
 *
 * A worker actively building breathes; one parked in maintenance sits still. That is the whole
 * distinction, and an animation carries it without inventing a health state — a colour would have to
 * compete with the health axis, which already means something else — and without changing the node's
 * static appearance at all.
 *
 * `fleet` gates it to the DRILLED fleet (L1). A project node on L0 must never animate, however busy
 * the project is — an L0 project in flight says so on the health axis (`modifying`, #4052), which is
 * still. The gate is an explicit flag rather than anything derived from the node, so a data change can
 * never quietly start animating the L0 layer.
 *
 * Suppressed on a deactivated node (meant to read calm) and on an errored one (its own error pulse is
 * the thing to look at; two competing animations on one node read as noise).
 *
 * Pure + exported so the gating is testable — the animation is an inline style, and what matters is
 * WHICH nodes get it, not the frames.
 */
export function showsBuildingPulse(
  n: { activity: GActivity },
  ctx: { fleet: boolean; isOff: boolean; isError: boolean },
): boolean {
  return ctx.fleet && !ctx.isOff && !ctx.isError && n.activity === "building";
}

/** Axis 2 — ACTIVITY (#2541): the bottom-right lifecycle word — what the project is doing right now.
 *  `idle` is the RESTING default (#2551): a triaged project with nothing running reads idle, NOT
 *  building — `building` means agents are ACTUALLY running (derived from live sessions, never a
 *  fallback). `planning` surfaces ONLY when the user has re-opened the planner on an already-triaged
 *  project (a re-edit state). `waiting` = an EXPECTED blocked state (an agent parked for the user,
 *  `bsc-wait`) — calm, not alarming; it lives here, not on the health axis. */
export type GActivity = "idle" | "planning" | "building" | "waiting" | "review" | "live" | "complete";
/** A Glance edge's kind. The project-network contracts (`api`/`data`/`events`) plus the CROSS-GRAPH
 *  LIBRARY edges: `uses-kit` (a project consumes a `bsc ui` kit, #2571) and the generalized `requires`
 *  (#3119, epic #3114) — a project/page pulls in an ALGORITHM or a SOUND library node — plus the EXTERNAL
 *  CONTRACT edges (#3786): `uses-mcp` (an MCP server) and `uses-service` (a third-party service). Every
 *  band edge ({@link isBandEdge}) routes vertically into the fenced band; the project contracts flow
 *  left→right. */
export type GEdgeKind = "api" | "data" | "events" | "uses-kit" | "requires" | "uses-mcp" | "uses-service" | "owned-by" | "served-by" | "depends-on" | "uses-integration" | "verb-of" | "belongs-to";
/** A Glance node's KIND (#2571 → generalized #3119 → external contracts #3786). A PROJECT (the default), a
 *  UI-KIT node (`kit`, the `ui` library graph — kept as-is so existing fixtures + persisted ids are
 *  unaffected), a generalized cross-graph `library` node (an algorithm / sound, carrying
 *  {@link GRawNode.library}), an `mcp` contract node (an external MCP server a project uses, #3786 Phase 1
 *  auto-derived + Phase 2 planner-declared), or a `service` contract node (a third-party service a project
 *  contracts with, #3786 Phase 2). ABSENT ⇒ `"project"`. A non-project node's id is namespaced (`kit:` /
 *  `algo:` / `sound:` / `mcp:` / `service:`, see {@link libraryNodeId} / {@link mcpNodeId} /
 *  {@link serviceNodeId}) so it can never collide with a project key (a `[a-z0-9-]` slug — no colon). */
export type GNodeKind = "project" | "kit" | "library" | "mcp" | "service" | "architect" | "session" | "surface" | "integration" | "feature";

/** The cross-graph LIBRARY dimensions a band node can belong to (#3119) — reuses A's {@link NodeGraph}
 *  (algorithms · UI kits · sounds). A `kit` node is the `ui` case (kept for back-compat); a generalized
 *  `library` node names its graph via {@link GRawNode.library}. */
export type GLibraryGraph = NodeGraph; // "algo" | "ui" | "sound"

/**
 * The READING ORDER of node kinds, for any list that groups by type (the Glance sidebar).
 *
 * Top-down it reads as what the project is built ON, then what it IS, then who runs it:
 *
 *   library · kit                shared records it consumes and does not own
 *   mcp · service · integration  external contracts it depends on — same kind of thing as a library,
 *                                something depended on and owned elsewhere, so it sits beside one
 *   feature                      the capabilities: the program itself
 *   surface                      the crates the program is decomposed into
 *   session · architect · project  the actors that operate on all of it
 *
 * EVERY kind has a rank on purpose. A `Record<GNodeKind, number>` makes adding a kind without deciding
 * where it reads a compile error, rather than letting it fall to an unspecified position that a reader
 * would take for a judgement someone made.
 *
 * This orders a LIST, never the canvas. The graph is DAG-layered with barycenter crossing-reduction,
 * and imposing a kind order there would fight the thing that makes its edges readable.
 */
export const NODE_KIND_ORDER: Record<GNodeKind, number> = {
  library: 0,
  kit: 0,
  mcp: 1,
  service: 1,
  integration: 1,
  feature: 2,
  surface: 3,
  session: 4,
  architect: 4,
  project: 4,
};

/** A node's rank in {@link NODE_KIND_ORDER}; kind-less nodes sort last rather than first. */
export const nodeKindRank = (n: { kind?: GNodeKind }): number =>
  n.kind ? NODE_KIND_ORDER[n.kind] : Number.MAX_SAFE_INTEGER;

/** UI-KIT node/edge accent (#2571) — a distinct cyan that stands apart from the lifecycle-category
 *  palette (teal/indigo/bronze/slate/magenta/gold), the health dots, and the iteration-loop violet, so a
 *  kit node + its `uses-kit` edges read as a separate relationship dimension. */
export const KIT_COLOR = "#22d3ee";
/** Algorithm-library accent (#3119) — violet. */
export const ALGO_COLOR = "#a78bfa";
/** Sound-library accent (#3119) — pink. */
export const SOUND_COLOR = "#f472b6";
/** MCP-contract accent (#3786) — amber, distinct from the library dimensions (cyan kit / violet algo /
 *  pink sound) so an external-contract node + its `uses-mcp` edges read as their own dimension. MCP nodes
 *  are dashed band cards with no health dot, so this never blurs with the warning-health orange. */
export const MCP_COLOR = "#f59e0b";
/** External-SERVICE accent (#3786 Phase 2) — indigo, distinct from every other band dimension (cyan kit /
 *  violet algo / pink sound / amber mcp) AND from the health palette (blue/green/orange/red), so a
 *  third-party service node + its `uses-service` edges read as their own contract dimension. Like the mcp
 *  node it is a dashed band card with no health dot. */
export const SERVICE_COLOR = "#818cf8";

/** The presentation row shared by every fenced-BAND node (#3119 + #3786) — the accent colour, the node
 *  glyph + kind word, the band header, the inspector panel title, the consumer-edge label, and the
 *  inspector blurb. Used per library-graph ({@link LIBRARY_META}) and for the MCP dimension ({@link MCP_META}). */
export type BandMeta = {
  color: string; marker: string; kindLabel: string; bandLabel: string; panelTitle: string; edgeLabel: string; blurb: string;
};

/** Per-library-graph presentation (#3119). The `ui` row is EXACTLY the pre-#3119 kit treatment
 *  (cyan · ◆ · "kit" · "UI KITS" · "UI KIT" · "uses kit"), so a kit-only graph stays byte-identical. */
export const LIBRARY_META: Record<GLibraryGraph, BandMeta> = {
  ui: {
    color: KIT_COLOR, marker: "◆", kindLabel: "kit", bandLabel: "UI KITS", panelTitle: "UI KIT", edgeLabel: "uses kit",
    blurb: "A shared `bsc ui` kit. Every project below consumes it — a design-system dependency, so a breaking kit change fans out to them all.",
  },
  algo: {
    color: ALGO_COLOR, marker: "∑", kindLabel: "algorithm", bandLabel: "ALGORITHMS", panelTitle: "ALGORITHM", edgeLabel: "requires",
    blurb: "A shared algorithm from the algorithms graph. Every project above requires it — a cross-graph library dependency, so the reference implementation is reused, not re-coded.",
  },
  sound: {
    color: SOUND_COLOR, marker: "♪", kindLabel: "sound", bandLabel: "SOUNDS", panelTitle: "SOUND", edgeLabel: "requires",
    blurb: "A shared sound cue from the sounds graph. Every project above requires it — a cross-graph library dependency.",
  },
};

/** MCP-contract node presentation (#3786) — an external MCP server a project uses. Rendered in the same
 *  fenced top band as the library dimensions, but distinct (amber · ⇄ · "mcp" · "MCP SERVERS") so it reads
 *  as an EXTERNAL wire contract rather than a bundled library. This is Phase 1 of the inter-app contract
 *  model — the endpoint-type discriminator lives on the consuming project's `appType`. */
export const MCP_META: BandMeta = {
  color: MCP_COLOR, marker: "⇄", kindLabel: "mcp", bandLabel: "MCP SERVERS", panelTitle: "MCP SERVER", edgeLabel: "contracts with",
  blurb: "An external MCP server this project contracts with — a wire contract to a tool/data server, scoped to the projects that use it (a global built-in is not a specific contract, so it is not drawn here).",
};

/** External-SERVICE contract node presentation (#3786 Phase 2) — a third-party service (a payments API, a
 *  SaaS backend, another team's endpoint) a project's planner has DECLARED it depends on. Rendered in the
 *  same fenced top band as the mcp + library dimensions, but distinct (indigo · ☁ · "service" ·
 *  "SERVICES") so it reads as an external, planner-declared wire contract. Its endpoint type lives on the
 *  node's `appType`. */
export const SERVICE_META: BandMeta = {
  color: SERVICE_COLOR, marker: "☁", kindLabel: "service", bandLabel: "SERVICES", panelTitle: "SERVICE", edgeLabel: "contracts with",
  blurb: "An external service this project contracts with — a third-party endpoint (a payments API, a SaaS backend, another team's service) the planner declared as a dependency, so the relationship is visible and downstream agents know the contract.",
};


/** COMMAND-SURFACE node presentation (`epic-command-surfaces-are-nodes`) — one node per CRATE, which
 *  is the 2026-09-01 decision: the node's job is MAINTENANCE, so every workspace member gets one and
 *  not only the ones that expose verbs. `bsc-util` exposes none and is the crate whose change reaches
 *  most of the workspace, so it is exactly the one that needs an owner. Whether a crate has verbs is a
 *  FACET, not the criterion for existing.
 *
 *  Teal + ⌘ so it reads apart from both the library dimensions and the external-contract ones: a
 *  surface is neither a bundled library nor a third-party wire contract, it is a door into THIS
 *  system. Deliberately NOT the `library` kind, which already means a cross-graph algorithm or sound. */
export const SURFACE_COLOR = "#2dd4bf";
export const SURFACE_META: BandMeta = {
  color: SURFACE_COLOR, marker: "\u2318", kindLabel: "surface", bandLabel: "COMMAND SURFACES", panelTitle: "COMMAND SURFACE", edgeLabel: "drives",
  blurb: "A crate of this workspace — the unit a maintaining session owns. Its verbs are the doors an agent drives the system through; a crate with none still has a node, because it still has to be maintained.",
};

/** Namespace prefix for a SURFACE node id — its own namespace for the same reason every other band
 *  has one: a bare `bsc-util` would be indistinguishable from a project key (`[a-z0-9-]`, no colon). */
export const SURFACE_NODE_PREFIX = "surface:";

/** FEATURE accent (`a-feature-is-a-node`) — violet, the one band accent left unspoken for.
 *
 *  A feature is neither a library you compose against nor a door you drive the system through: it is a
 *  UNIT OF WORK, the thing streams are grouped under and issues are sequenced within. It gets its own
 *  colour because reusing an existing one would say it is the same kind of thing as that band, and it
 *  is not. */
export const FEATURE_COLOR = "#a78bfa";
export const FEATURE_META: BandMeta = {
  color: FEATURE_COLOR, marker: "\u25c9", kindLabel: "feature", bandLabel: "FEATURES", panelTitle: "FEATURE", edgeLabel: "belongs to",
  blurb: "A unit of work in this project's plan. Its STREAMS drill down beneath it — one lane each, with their own worktrees and workers — and its `requires` names the records from the shared graphs it builds against. A feature with no streams still has a node: an unstaffed lane is exactly the one worth seeing.",
};

/** Namespace prefix for a FEATURE node id.
 *
 *  Its own namespace for the reason every band has one, and here the collision is REAL rather than
 *  theoretical: 37 of studio-code's 89 stream ids ARE feature slugs, so a bare `glance` would be
 *  ambiguous between the feature and the stream that shares its name. */
export const FEATURE_NODE_PREFIX = "feature:";

/**
 * The stable id of a feature node, keyed on the plan slug — and on the REPO when the feature has work
 * in more than one.
 *
 * A feature whose streams span repositories draws ONE NODE PER BAND rather than being forced into a
 * majority (which erases the minority) or left unbanded (which says it belongs to no repository at
 * all). `mobile-tunnel` is the real case: one stream in base-studio-code, two in mobile-studio-code.
 *
 * The suffix is OMITTED for a single-repo feature so the ids that already work do not churn, and
 * because most features are single-repo — carrying `@repo` on all of them would be noise in every id
 * for the sake of one. A feature slug is kebab-case (`[a-z0-9-]`), so `@` cannot occur in one and is
 * an unambiguous separator.
 *
 * The DUPLICATION IS SAFE because cross-repo coherence is not this graph's job — it is enforced
 * through the components and algorithms graphs and their relationships (maintainer, 2026-09-03), so
 * two nodes for one feature cannot drift into two different answers about anything that matters.
 */
export const featureNodeId = (slug: string, repo?: string): string =>
  repo ? `${FEATURE_NODE_PREFIX}${slug}@${repo}` : `${FEATURE_NODE_PREFIX}${slug}`;

/** Is `id` a feature node? A PREDICATE — see {@link isSurfaceNodeId} for why the converter is not one. */
export const isFeatureNodeId = (id: string): boolean => id.startsWith(FEATURE_NODE_PREFIX);

/**
 * The feature slug behind a node id, or the id unchanged when it carries no prefix.
 *
 * Cuts at the `@` too, so a per-repo node drills the ONE feature it is a band of — both of
 * `mobile-tunnel`'s nodes open `mobile-tunnel`. See {@link featureNodeId} for why the suffix exists.
 */
export const featureSlugOfNode = (nodeId: string): string => {
  if (!nodeId.startsWith(FEATURE_NODE_PREFIX)) return nodeId;
  const rest = nodeId.slice(FEATURE_NODE_PREFIX.length);
  const at = rest.indexOf("@");
  return at < 0 ? rest : rest.slice(0, at);
};

/** The drill namespace for one of a feature's STREAMS. Keyed on FEATURE AND STREAM, never the stream
 *  alone: a stream id is unique within a project, but the node lives inside one feature's drill and
 *  the id should say which. */
export const featureStreamNodeId = (feature: string, stream: string): string =>
  `fstream:${feature}:${stream}`;

/** The `belongs-to` edge from a stream up to its feature. */
export const belongsToEdgeId = (feature: string, stream: string): string =>
  `belongs-to:${feature}:${stream}`;

/** The drill namespace for a record a feature REQUIRES. Keyed on the feature too, because the same
 *  record is legitimately required by several features and each drill shows its own copy. */
export const featureRequiresNodeId = (feature: string, recordId: string): string =>
  `freq:${feature}:${recordId}`;

/** The stable, collision-proof id of a surface node. Keyed on the cargo PACKAGE name, never the
 *  directory and never the lib target — `crates/data` is `bsc-data`, `crates/llm` is `bsc-llm`, and
 *  the dispatch writes `llm::cli::run` for the last of those. Everything else in the repo refers to a
 *  crate by its package, so that is what a node is keyed on. */
export const surfaceNodeId = (crate: string): string => `${SURFACE_NODE_PREFIX}${crate}`;

/** The second layer's node namespace — one node per `bsc <noun> <verb>`. */
export const SURFACE_VERB_PREFIX = "verb:";

/** The second layer's ROOT namespace — one node per `bsc <noun>`. */
export const SURFACE_NOUN_PREFIX = "noun:";

/** A noun node's id — the root of one command's verb tree. Its own prefix rather than a verb node with
 *  an empty verb, so the id reads as what it is and cannot collide with a verb however odd its name. */
export const nounNodeId = (noun: string): string => `${SURFACE_NOUN_PREFIX}${noun}`;

/**
 * A verb node's id — keyed on NOUN AND VERB, never the verb alone.
 *
 * `bsc logs summary` and `bsc mem summary` are different commands, and the `logs` crate alone serves
 * three nouns. Keying on the verb would collide them into one node and silently drop the others.
 */
export const verbNodeId = (noun: string, verb: string): string => `${SURFACE_VERB_PREFIX}${noun}:${verb}`;

/** Is `id` a verb node? */
export const isVerbNodeId = (id: string): boolean => id.startsWith(SURFACE_VERB_PREFIX);

/** The `verb-of` edge from a verb back to the noun that answers it. */
export const verbOfEdgeId = (crate: string, noun: string, verb: string): string =>
  `verb-of:${crate}:${noun}:${verb}`;

/**
 * Is `id` a crate node? A PREDICATE, which {@link surfaceCrateOfNode} is not.
 *
 * That distinction cost a live regression: `surfaceCrateOfNode` returns the id UNCHANGED when there is
 * no prefix, so `if (surfaceCrateOfNode(id))` is true for every node ever passed to it. Used as a
 * click guard it routed every node in a drill — sessions included — into the crate layer, and killed
 * session expansion outright. A converter is not a test.
 */
export const isSurfaceNodeId = (id: string): boolean => id.startsWith(SURFACE_NODE_PREFIX);

/** The crate behind a surface node id, or the id unchanged when it carries no prefix. */
export const surfaceCrateOfNode = (nodeId: string): string =>
  nodeId.startsWith(SURFACE_NODE_PREFIX) ? nodeId.slice(SURFACE_NODE_PREFIX.length) : nodeId;

/** The stable id of a crate-dependency edge between two surface nodes. */
export const dependsOnEdgeId = (fromCrate: string, toCrate: string): string => `cratedep:${fromCrate}>${toCrate}`;

/** INTEGRATION node presentation (`an-integration-is-a-glance-node-with-a-real-signal`) — an existing
 *  application or API this estate integrates with.
 *
 *  Its own kind rather than a reuse of `service`, and the difference is what the node can SAY. A
 *  `service` is a hand-declared endpoint with a URL and nothing behind it; an integration is backed by
 *  a probed, tried, registered manifest with resources, field shapes and a verification verdict, so it
 *  can report "last verified live, 12 resources" where a service node structurally cannot. Reusing
 *  `service` would flatten that and force the service kind to grow integration-specific state.
 *
 *  ⇄ for the direction — an integration is a system we READ, and the arrow says so.
 *
 *  THE HUE IS A CONSTRAINED CHOICE, not a free one, and the constraint is worth stating because the
 *  next person will want to change it. Green, blue, orange and red belong to HEALTH (`HEALTH_META`),
 *  and this is the one band whose entire point is that its dot means something — an accent in a health
 *  hue would make every integration node read as a status. Amber, indigo, teal, violet, pink, cyan,
 *  slate and tan are the eight band accents already spoken for. Fuchsia is what is left that is
 *  neither: 31° from the algorithms violet and 41° from the sounds pink, which is not generous — the
 *  palette is crowded and this file already records hue fights at 19° and 27°. It is the least-bad
 *  remaining hue rather than an obvious one, and a deliberate re-palette would be a better answer
 *  than squeezing an eleventh accent in after this. */
export const INTEGRATION_COLOR = "#d946ef";
export const INTEGRATION_META: BandMeta = {
  color: INTEGRATION_COLOR, marker: "\u21c4", kindLabel: "integration", bandLabel: "INTEGRATIONS", panelTitle: "INTEGRATION", edgeLabel: "integrates with",
  blurb: "An existing application or API a project integrates with \u00b7 declared at Discovery, built by the Integrator as a connector, and verified read-only. Its dot is the last verification: no signal until something has actually been read.",
};

/** Namespace prefix for an INTEGRATION node id \u2014 its own namespace, because an integration id is a
 *  bare slug (`stripe`, `salesforce`) and would otherwise be indistinguishable from a project key. */
export const INTEGRATION_NODE_PREFIX = "integration:";

/** The stable id of an integration node, keyed on the DECLARED id \u2014 the same slug
 *  `bsc plan discovery integration` stores and `bsc data connector` registers, which is what lets the
 *  demand side and the supply side join at all. */
export const integrationNodeId = (id: string): string => `${INTEGRATION_NODE_PREFIX}${id}`;

/** The integration behind a node id, or the id unchanged when it carries no prefix. */
export const integrationIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(INTEGRATION_NODE_PREFIX) ? nodeId.slice(INTEGRATION_NODE_PREFIX.length) : nodeId;

/** The stable id of a project\u2192integration edge. Keyed on both ends, because ONE integration is
 *  routinely declared by several projects and each of those is its own edge. */
export const usesIntegrationEdgeId = (projectKey: string, integrationId: string): string =>
  `usesintegration:${projectKey}>${integrationId}`;

/** ARCHITECT node presentation (#glance-architect-band) — the funnel's tier 1, the only session that
 *  converses with the user. Rendered in the same fenced top band as the library + contract dimensions,
 *  but distinct (amber · ◈ · "architect" · "ARCHITECTS") so the tier that CREATES projects reads apart
 *  from the dependencies they consume. */
export const ARCHITECT_COLOR = "#e0a458";
export const ARCHITECT_META: BandMeta = {
  color: ARCHITECT_COLOR, marker: "◈", kindLabel: "architect", bandLabel: "ARCHITECTS", panelTitle: "ARCHITECT", edgeLabel: "created by",
  blurb: "The architect session that creates projects — the funnel's front door, and the only tier that talks to you. It runs discovery and hands a sealed requirement (plus the authority granted with it) down to each project's director.",
};

/** SYSTEM-SESSION node presentation (#glance-reads-left-to-right-sessions-to-libraries) — the app-owned
 *  singleton studios (designer · librarian · sound-designer · integrator) that produce the material a
 *  build runs on. Like the architect these are NETWORK nodes, not band nodes: they take a layer from the
 *  DAG, which is what places them left of the architect. Slate + ◇ so they read as the quiet upstream of
 *  the funnel rather than competing with the architect's amber. */
export const SESSION_COLOR = "#8b93a7";
export const SESSION_META: BandMeta = {
  color: SESSION_COLOR, marker: "◇", kindLabel: "session", bandLabel: "SYSTEM SESSIONS", panelTitle: "SYSTEM SESSION", edgeLabel: "served by",
  blurb: "An app-owned studio session — a singleton the app launches on demand rather than a fleet worker. These produce the material every build runs on: UI kits, algorithms, sounds, and integration connectors.",
};

/** Namespace prefix for a SYSTEM-SESSION node id — its own namespace, for the same reason the architect
 *  has one: a bare `designer` would be indistinguishable from a project key.
 *
 *  NOTE (#architect-node-expands-into-system-sessions): the L0 graph no longer EMITS these. The system
 *  sessions moved into the architect node's drill-in, which is built by the Team→Glance adapter and so
 *  produces `agent` nodes. This vocabulary — the id namespace, `SESSION_META`, `SESSION_COLOR` and the
 *  `served-by` edge row — is kept rather than deleted because it is shared presentation the inspector
 *  and legend still read from, and because the L0 row is a layout decision that could reasonably come
 *  back. Nothing constructs a `session` NODE today; if that is still true next time someone is here,
 *  retiring the kind is a contained edit in this file. */
export const SESSION_NODE_PREFIX = "session:";
/** The stable, collision-proof id of the graph node for an app-owned system session. */
export const sessionNodeId = (sessionId: string): string => `${SESSION_NODE_PREFIX}${sessionId}`;
/** The session id behind a `session:<id>` node id (identity for anything already bare). */
export const sessionIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(SESSION_NODE_PREFIX) ? nodeId.slice(SESSION_NODE_PREFIX.length) : nodeId;
/** Stable id for an architect→session `served-by` edge — prefixed so it never collides with any other
 *  edge id. */
export const servedByEdgeId = (personaId: string, sessionId: string): string => `servedby:${personaId}>${sessionId}`;

/**
 * Which node the open-morph GRID is measured from, given the anchor the user's first open chose.
 *
 * ## Why this is not just `nodes.find(n => n.id === anchorId)`
 *
 * The morph grid derives every open panel's slot from ONE anchor node's live coordinates, and the
 * anchor is retained after its own morph closes so the surviving panels never shift under the user.
 * That retention is the whole point — and it means the stored id can outlive the node.
 *
 * When it did, `anchorNode` went null and the derivation dropped EVERY morph at once, permanently:
 * `placements` was still non-empty, so nothing cleared the anchor, and nothing re-derived it. The
 * user saw every open node go blank and stay blank until they closed and reopened them.
 *
 * That is precisely the property #3361 set out to establish and did not finish. It made the LIVENESS
 * guard per-morph ("one agent going away drops just its morph") but left the anchor lookup as a
 * shared, all-or-nothing gate — so one node leaving the graph still took the whole grid with it,
 * through the one guard that had not been split.
 *
 * Falling back to the first placement that still resolves keeps the panels alive. The grid re-anchors
 * once, which does move it — but a grid that shifts is strictly better than a grid that vanishes, and
 * the stable-placement promise was never worth honouring by showing nothing.
 *
 * Pure: ids in, id out. Returns `null` only when NOTHING resolves, which is the honest "there is no
 * grid" case (every morphed node is gone).
 */
export function resolveGridAnchor(
  anchorId: string | null,
  placementNodeIds: readonly string[],
  presentNodeIds: ReadonlySet<string>,
): string | null {
  if (anchorId && presentNodeIds.has(anchorId)) return anchorId;
  return placementNodeIds.find((id) => presentNodeIds.has(id)) ?? null;
}

/** Namespace prefix for an ARCHITECT node id — its own namespace so it can never collide with a project
 *  key (a `[a-z0-9-]` slug, no colon) or another band node id. */
export const ARCHITECT_NODE_PREFIX = "architect:";
/** The stable, collision-proof id of the graph node for an architect persona. */
export const architectNodeId = (personaId: string): string => `${ARCHITECT_NODE_PREFIX}${personaId}`;
/** Whether a node id names an ARCHITECT persona — the L0 node that expands into the system sessions
 *  it commands (#architect-node-expands-into-system-sessions). Prefix-keyed, like every other band
 *  namespace, so it can never mistake a project key (a `[a-z0-9-]` slug, no colon) for one. */
export const isArchitectNodeId = (nodeId: string): boolean => nodeId.startsWith(ARCHITECT_NODE_PREFIX);
/** The persona id behind an `architect:<personaId>` node id (identity for anything already bare). */
export const architectIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(ARCHITECT_NODE_PREFIX) ? nodeId.slice(ARCHITECT_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→architect `owned-by` edge — prefixed so it never collides with any other
 *  edge id. */
export const ownedByEdgeId = (projectKey: string, personaId: string): string => `ownedby:${projectKey}>${personaId}`;

/** Namespace prefix for a KIT node id (#2571). */
export const KIT_NODE_PREFIX = "kit:";
/** graph → the namespace prefix for a library node id (#3119). `ui` stays `kit:` so {@link kitNodeId}
 *  and every persisted `kit:<id>` node id are unchanged; algo/sound get their own namespaces. */
export const LIBRARY_NODE_PREFIX: Record<GLibraryGraph, string> = { ui: KIT_NODE_PREFIX, algo: "algo:", sound: "sound:" };
/** The stable, collision-proof id of a library node in `graph` (#3119). `libraryNodeId("ui", x)` is
 *  exactly {@link kitNodeId}`(x)`. */
export const libraryNodeId = (graph: GLibraryGraph, libId: string): string => `${LIBRARY_NODE_PREFIX[graph]}${libId}`;
/** The stable, collision-proof id of the graph node for a `bsc ui` kit (#2571). */
export const kitNodeId = (kitId: string): string => `${KIT_NODE_PREFIX}${kitId}`;
/** The kit id behind a `kit:<kitId>` node id (identity for anything already bare). */
export const kitIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(KIT_NODE_PREFIX) ? nodeId.slice(KIT_NODE_PREFIX.length) : nodeId;
/** The in-graph library id behind a library node id (#3119), stripping whichever graph prefix matches. */
export const libIdOfNode = (nodeId: string): string => {
  for (const p of Object.values(LIBRARY_NODE_PREFIX)) if (nodeId.startsWith(p)) return nodeId.slice(p.length);
  return nodeId;
};
/** Stable id for a project→kit `uses-kit` edge (#2571) — prefixed so it can never collide with a
 *  {@link projectLinkId} (`from>to:kind`). */
export const usesKitEdgeId = (projectKey: string, kitId: string): string => `usekit:${projectKey}>${kitId}`;
/** Stable id for a project→library `requires` edge (#3119) — prefixed so it never collides with a
 *  {@link projectLinkId} or a {@link usesKitEdgeId}. `toNodeId` is the target library node id. */
export const requiresEdgeId = (fromKey: string, toNodeId: string): string => `req:${fromKey}>${toNodeId}`;

/** Namespace prefix for an MCP-contract node id (#3786) — its own namespace so it never collides with a
 *  project key or a library node id (`kit:`/`algo:`/`sound:`). */
export const MCP_NODE_PREFIX = "mcp:";
/** The stable, collision-proof id of the graph node for an MCP server (#3786). */
export const mcpNodeId = (serverId: string): string => `${MCP_NODE_PREFIX}${serverId}`;
/** The MCP server id behind an `mcp:<serverId>` node id (identity for anything already bare). */
export const mcpIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(MCP_NODE_PREFIX) ? nodeId.slice(MCP_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→mcp `uses-mcp` edge (#3786) — prefixed so it never collides with a
 *  {@link projectLinkId}, a {@link usesKitEdgeId}, or a {@link requiresEdgeId}. */
export const usesMcpEdgeId = (projectKey: string, serverId: string): string => `usemcp:${projectKey}>${serverId}`;

/** Namespace prefix for an external-SERVICE contract node id (#3786 Phase 2) — its own namespace so it
 *  never collides with a project key or another band node id (`kit:`/`algo:`/`sound:`/`mcp:`). */
export const SERVICE_NODE_PREFIX = "service:";
/** The stable, collision-proof id of the graph node for an external service (#3786 Phase 2). `serviceId`
 *  is the contract's `to` endpoint (the service name/slug the planner declared). */
export const serviceNodeId = (serviceId: string): string => `${SERVICE_NODE_PREFIX}${serviceId}`;
/** The service id behind a `service:<serviceId>` node id (identity for anything already bare). */
export const serviceIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(SERVICE_NODE_PREFIX) ? nodeId.slice(SERVICE_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→service `uses-service` edge (#3786 Phase 2) — prefixed so it never collides
 *  with a {@link projectLinkId}, a {@link usesKitEdgeId}, a {@link requiresEdgeId}, or a {@link usesMcpEdgeId}. */
export const usesServiceEdgeId = (projectKey: string, serviceId: string): string => `usesvc:${projectKey}>${serviceId}`;

/** Is `n` a cross-graph LIBRARY node (#3119) — a lifted band node, not a project? True for a legacy `kit`
 *  node (the `ui` graph) or a generalized `library` node (algo/sound/ui). */
export const isLibraryNode = (n: { kind?: GNodeKind }): boolean => n.kind === "kit" || n.kind === "library";
/** The library graph a node belongs to (#3119): `kit` ⇒ `"ui"` (back-compat), a `library` node ⇒ its
 *  `library` field (defaulting to `"ui"`), else undefined (a project). */
export const libraryGraphOf = (n: { kind?: GNodeKind; library?: GLibraryGraph }): GLibraryGraph | undefined =>
  n.kind === "kit" ? "ui" : n.kind === "library" ? (n.library ?? "ui") : undefined;
/** Is `kind` a cross-graph LIBRARY edge (#3119) — a `uses-kit` (ui) or generalized `requires` edge? These
 *  route VERTICALLY into the fenced band and are excluded from the project-network layout. */
export const isLibraryEdge = (kind: GEdgeKind): boolean => kind === "uses-kit" || kind === "requires";

/** The ARCHITECT is deliberately NOT here (#architect-sits-with-the-projects). Every other non-project
 *  node in this graph is a shared DEPENDENCY — a kit, an algorithm, an MCP server — and lifting those
 *  keeps their health out of a project's roll-up and their edges out of the project DAG. An architect is
 *  the opposite relationship: it CREATED these projects rather than being consumed by them, so it belongs
 *  beside them in the same network. It is safe there because it is a SINK — every `owned-by` edge
 *  points AT it — and a cycle needs a path back out.
 *
 *  Is `n` a fenced-BAND node (#3786) — ANY lifted non-project node: a library node (kit/algorithm/sound)
 *  OR an external contract node (`mcp` / `service`). These are lifted OUT of the project DAG into the top
 *  band. */
export const isBandNode = (n: { kind?: GNodeKind }): boolean =>
  isLibraryNode(n) || n.kind === "mcp" || n.kind === "service" || n.kind === "integration";

/* A SURFACE (crate) node is NOT banded, for the architect's reason (`architect-sits-with-the-projects`).
 * The band is for a shared DEPENDENCY the projects CONSUME — a kit, an algorithm, an MCP server — where
 * lifting keeps its health out of a project's roll-up and its edges out of the project DAG. A crate is
 * not consumed by the project; it IS the project, decomposed. Fencing it says the opposite of what is
 * true, and it renders 60 crates as an inventory beside the work rather than as the work.
 *
 * SAFE because the crate graph is a DAG: measured 60 crates / 230 edges / 0 cycles, and cargo cannot
 * express a cycle in normal dependencies. `depends-on` therefore leaves the band-edge set too, so it
 * routes as an ordinary edge. Pinned by `surfaceNodesAreNotBanded` — a cycle here has blanked this
 * graph before (glance-planner-edge-isolation). */
/** Is `kind` a BAND edge (#3786) — a library edge OR an external-contract edge (`uses-mcp`/`uses-service`).
 *  These route VERTICALLY into the fenced band and are excluded from the project-network layout. */
export const isBandEdge = (kind: GEdgeKind): boolean =>
  isLibraryEdge(kind) || kind === "uses-mcp" || kind === "uses-service" || kind === "uses-integration";
/** The band presentation ({@link BandMeta}) for a fenced-band node (#3786) — the MCP row for an `mcp`
 *  contract node, the SERVICE row for a `service` contract node, else the library-graph row for a
 *  kit/algorithm/sound node. */
export const bandNodeMeta = (n: { kind?: GNodeKind; library?: GLibraryGraph }): BandMeta =>
  n.kind === "session" ? SESSION_META
  : n.kind === "architect" ? ARCHITECT_META
  : n.kind === "mcp" ? MCP_META
  : n.kind === "service" ? SERVICE_META
  : n.kind === "feature" ? FEATURE_META
  : n.kind === "surface" ? SURFACE_META
  : n.kind === "integration" ? INTEGRATION_META
  : LIBRARY_META[libraryGraphOf(n) ?? "ui"];

/** One communication form on a fleet node's comms surface (#2563) — a typed interaction + its `bsc-*`
 *  runtime transport, pared from the Org model so the glance node model stays decoupled from it. */
export interface GNodeCommForm { label: string; transport?: string }
/** A fleet node's communication surface with ONE counterpart (#2563), derived from the fleet-as-Org
 *  projection: the archetype, the other agent, and the forms this node SENDS / RECEIVES across it. */
export interface GNodeComm { withName: string; archetypeLabel: string; hue: number; sends: GNodeCommForm[]; receives: GNodeCommForm[] }

/** The agent identity behind a fleet node (#2561) — the persona surfaced on the drill node + inspector,
 *  so the user sees WHO is at that terminal (name · role · model · skills · charter), not just a role. */
export interface GNodePersona {
  name: string;
  role: string;
  model?: string;
  skills: string[];
  responsibilities: string[];
  /** The agent's communication surface (#2563) — who it talks to and how, one entry per relationship,
   *  derived from the fleet-as-Org projection. Absent until computed (fleet drill only). */
  comms?: GNodeComm[];
}

/** Severity rank for the health rollup — only `warning`/`error` (rank ≥ 1) propagate up dependency
 *  edges; everything else is "no problem" (rank 0) and stays put. */
// `complete` is rank 0 — finished is not a problem, so it must never propagate up a dependency edge
// and light a parent that is perfectly fine. `modifying` (#4052) is rank 0 for the same reason: work
// being IN FLIGHT is the normal state of a live project, and a dependency that is merely busy must
// never make its dependents look degraded.
export const HEALTH_RANK: Record<GHealth, number> = { healthy: 0, complete: 0, modifying: 0, warning: 1, error: 2, off: 0 };

/** A project node as supplied by the data adapter (before layout). */
export interface GRawNode {
  id: string;
  /** Owned-issue completion (#4050) — `done / total` for this node's stream. Absent for a node with no
   *  stream, or before the first read lands. PRESENTATIONAL ONLY: it never feeds health or activity,
   *  so a stale or missing read can never change what state the node reports. */
  progress?: { done: number; total: number };
  /** Display name (defaults to id). */
  slug?: string;
  role: GRole;
  /** The DISCOVERED lifecycle intent (#4062) — the L0 project node's accent chip. Absent for an
   *  unclassified project (⇒ no chip; see {@link LIFECYCLE_META}) and for fleet-drill (L1) nodes,
   *  which show their function group there instead. */
  lifecycle?: string;
  /** Axis 1 — the node's OWN health (before the dependency rollup). #2541. */
  health: GHealth;
  /** Axis 2 — the lifecycle word shown bottom-right. #2541. */
  activity: GActivity;
  /** When health is `warning`/`error`, the short reason (the `Fault.title` that set it) shown in place
   *  of the activity word, so the user sees WHY the dot changed. #2541. */
  reason?: string;
  /** Optional director id (for the node badge / inspector). */
  director?: string;
  /** The REPOSITORY this node's work lives in, `owner/name` exactly as the plan records it — the key the
   *  fleet drill groups by ({@link RepoBand}). Carried from the stream's own `repo`, which `bsc plan
   *  fleet set` already validates as required, so this is a projection of existing data rather than a
   *  new fact anyone has to maintain.
   *
   *  ABSENT is meaningful and common: the architect, the peer directors, the system sessions and the
   *  debug sessions are project- or app-scoped, not repo-scoped. Those stay OUTSIDE every band. */
  repo?: string;
  /** Display label for the role when the mapped `role` category isn't the real thing — e.g. a fleet
   *  agent's actual session role ("worker" / "reviewer" / "director"), from its persona. The `role`
   *  category still drives the colour; this is the text shown on the card + inspector. */
  roleLabel?: string;
  /** Unresolved runtime-fault count for the project (#2265), from `bsc errors` — surfaced in the
   *  inspector. The count's worst LEVEL drives `health` (#2541); absent/0 ⇒ healthy/idle. */
  faults?: number;
  /** The agent identity at this node (#2561) — set for fleet-drill (L1) nodes, absent for project (L0)
   *  nodes. The inspector renders it as the persona card. */
  persona?: GNodePersona;
  /** The PREVIEW node (#2623) — not an agent: the surface that renders the finished application in the
   *  graph when the project is complete. Clicking it morphs open the app preview (`GlancePreviewMorph`)
   *  the way an agent node morphs open its terminal. The canvas renders it distinctly (▷). */
  preview?: boolean;
  /** A shared-RESOURCE node (#3322) — a team position of `kind:"resource"` (a library a session stewards,
   *  not an agent). The canvas renders it as a distinct dashed card so it never reads as a worker/agent. */
  resource?: boolean;
  /** The node KIND (#2571 → generalized #3119) — `"kit"` for a UI-kit node, `"library"` for a generalized
   *  cross-graph library node (algorithm / sound), else a PROJECT node. ABSENT ⇒ `"project"` so existing
   *  nodes/tests are unaffected; the canvas + inspector render a library node distinctly (its graph glyph
   *  · kind word · consumer count). */
  kind?: GNodeKind;
  /** The library graph this node belongs to (#3119) — set on a generalized `library` node to say which
   *  cross-graph dimension it is (`algo`/`sound`/`ui`). A legacy `kit` node leaves this ABSENT (it is
   *  implicitly `ui`). Absent on a project. */
  library?: GLibraryGraph;
  /** The project's APPLICATION ARCHITECTURE (#3786/#3802) — the contract endpoint-type discriminator:
   *  application/api/serverless/static/desktop/mobile/cli/library. Set on a PROJECT node from
   *  `planClassification[key].appType` (absent ⇒ "application"/unknown, rendered plain); on an `mcp`
   *  contract node from its transport (http ⇒ api, stdio ⇒ serverless) or a planner-declared `--app-type`;
   *  and on a `service` contract node from the planner-declared `--app-type` (#3786 Phase 2). Absent on
   *  library/kit nodes. */
  appType?: AppType;
}
/** A dependency edge: `from` depends on `to`, over a contract of `kind`. Optional stable `id` (a
 *  user-drawn project link carries its own; sample/derived edges fall back to a positional id).
 *  `archetype` (#2561) is the Org relationship archetype id for a fleet-drill (L1) edge — Manages /
 *  Oversees / Peers / … — which drives the edge colour + the communication forms shown in the inspector;
 *  absent for project (L0) edges, which keep the `kind` vocabulary. */
export interface GRawEdge { from: string; to: string; kind: GEdgeKind; id?: string; archetype?: string }

export interface GNode extends GRawNode {
  slug: string; layer: number; x: number; y: number;
  /** Health after the up-the-chain rollup (#2541): the worst of this node's own `health` and every node
   *  it (transitively) depends on. This is what the top-left dot renders. */
  rollupHealth: GHealth;
  /** True when `rollupHealth` is worse than the node's OWN `health` — i.e. the node is only lit because
   *  of a downstream dependency. Renders as a MUTED dot (the origin keeps the full/pulsing treatment). */
  healthInherited: boolean;
}
export interface GEdge {
  id: string; from: string; to: string; kind: GEdgeKind;
  /** A hard dependency (api/data) blocks the consumer on a breaking change; events are soft. */
  hard: boolean;
  isCycle: boolean;
  /** Org relationship archetype id for a fleet-drill (L1) edge (#2561) — drives colour + the inspector's
   *  communication forms. Absent for project (L0) edges. */
  archetype?: string;
  /** SVG path + arrowhead in world coordinates. */
  d: string; arrow: string;
}

export interface GraphModel {
  nodes: GNode[];
  edges: GEdge[];
  /** Mutual-dependency pairs (a↔b) — the coordination hazards. */
  cyclePairs: [string, string][];
  cycleNodeIds: Set<string>;
  worldW: number;
  worldH: number;
  /** The fenced LIBRARY band across the top (#3007, generalized #3119) — the vertical zone [`y0`, `y1`]
   *  the lifted library nodes occupy (UI kits AND/OR algorithms/sounds), with `y1` the fence divider below
   *  them. ABSENT when the graph has no library nodes, so a project-only graph is unchanged. The canvas
   *  draws a tinted backdrop + divider + a header label (the graph's name for a single-dimension band —
   *  "UI KITS"/"ALGORITHMS"/"SOUNDS" — else "LIBRARIES"). The field name stays `kitBand` for persist/test
   *  stability. */
  bandZone?: { x0: number; x1: number };
  /** The REPOSITORY groups in a fleet drill — one full-width horizontal band per repo, stacked, each
   *  holding that repo's nodes. ABSENT when the graph has fewer than two repos, which is why the L0
   *  project network (whose nodes are projects and carry no repo) is completely unchanged. */
  repoBands?: RepoBand[];
}

/** One repository group in a fleet drill — the zone its nodes occupy: vertical [`y0`, `y1`], and
 *  starting at `x0`, which is the LEFT FENCE past everything ungrouped. The band runs from there to the
 *  right edge of the world. */
export interface RepoBand {
  /** `owner/name`, exactly as the plan records it — the identity, matched against {@link GRawNode.repo}. */
  repo: string;
  /** What the canvas prints. The bare repo name: the owner is the same on every band in a project, so
   *  repeating it costs width and distinguishes nothing. */
  label: string;
  /** The left fence — clear of the architect and the whole director/system tier, so the groups sit
   *  BESIDE that structure rather than underneath it. */
  x0: number;
  y0: number;
  y1: number;
}

/**
 * Project LIFECYCLE INTENT → accent colour + label (#4062) — the L0 project node's lower-left chip.
 *
 * The vocabulary is `Lifecycle` (`planner/lib/classifyConfig.ts`), DISCOVERED per project by the
 * planner at the Discovery stage (`bsc plan classify set`). Typed structurally rather than importing
 * the planner's type, so the graph model stays free of a cross-feature value import.
 *
 * ── NO DEFAULT, EVER ────────────────────────────────────────────────────────────────────────────
 * A project with no discovered lifecycle renders NOTHING here. This is the entire lesson of #4052,
 * which deleted the previous incarnation: `resolveProjectCategory` ended in `isDraft ? greenfield :
 * maintain`, so every unclassified project wore a confident label and six of them carried one bit of
 * real information between them. `lifecycleOf`'s `?? "greenfield"` default exists for STAGE GATING,
 * where a missing value must not hide a stage — it is exactly wrong for display, where a blank slot
 * is honest and a defaulted label is a lie that looks like data.
 */
export const LIFECYCLE_META: Record<string, { label: string; color: string }> = {
  greenfield: { label: "greenfield", color: "var(--graph-lifecycle-greenfield)" }, // build from a pitch
  transform:  { label: "transform",  color: "var(--graph-lifecycle-transform)" },  // restructure existing repos
  harden:     { label: "harden",     color: "var(--graph-lifecycle-harden)" },     // improve in place
  maintain:   { label: "maintain",   color: "var(--graph-lifecycle-maintain)" },   // keep a shipped system running
  harvest:    { label: "harvest",    color: "var(--graph-lifecycle-harvest)" },    // extract data out of sources (#4062)
};

/** Role → accent colour (drives the node left-border + role chip + legend). */
export const ROLE_COLOR: Record<GRole, string> = {
  infra: "var(--graph-kind-infra)", service: "var(--graph-kind-service)", data: "var(--graph-kind-data)", client: "var(--graph-kind-client)",
};
/** Axis 1 — HEALTH → the top-left dot colour + whether it pulses (#2541). Blue = finished, green =
 *  active & fine, orange = warning, red = error/fatal (pulses; the node to look at).
 *
 *  A pulse also has a CHARACTER (#4052), because two states now pulse for opposite reasons. `error`
 *  is an ALARM — fast, and haloed so it carries across the graph. `modifying` is a BREATH — slower and
 *  bare, so a busy project reads as alive without competing with a broken one for the eye. Both
 *  fields default to the alarm shape, so `error` is untouched. */
export const HEALTH_META: Record<GHealth, { label: string; color: string; pulse: boolean; pulseMs?: number; glow?: boolean }> = {
  // #4034 — the worker FINISHED. Blue, the palette's most alive colour, which was previously spent
  // on `idle` (a resting node) while the state that had actually achieved something had none.
  // Never pulses: complete is STILL, the same reason its activity carries no motion (#4032).
  complete: { label: "complete", color: "var(--graph-health-complete)", pulse: false },
  // #4052 — work IN FLIGHT. Deliberately COMPLETE'S OWN BLUE, separated by motion alone: modifying is
  // "on its way to complete", so sharing the hue is the point, and still-vs-breathing carries the rest.
  // Every hue freed by deleting the lifecycle palette crowded an existing health colour anyway (teal
  // 19° from healthy, slate 7° from complete, violet 27°, pink 35°) — the same too-close-to-blue
  // objection that ruled out a purple attention state. So this state costs the palette no new hue.
  modifying: { label: "modifying", color: "var(--graph-health-modifying)", pulse: true, pulseMs: 2600, glow: false },
  healthy: { label: "healthy", color: "var(--graph-health-healthy)", pulse: false },
  warning: { label: "warning", color: "var(--graph-health-warning)", pulse: false },
  error: { label: "error", color: "var(--graph-health-error)", pulse: true },
  // #3239 — the user-deactivated node: a muted grey dot, never pulsing. The manual "turned off" state.
  // #4042 — `off` now means "NO LIVE SESSION behind this node", which covers all three ways that
  // happens: the user deactivated it, it was never launched, or it is structural furniture (a kit, a
  // library, an external contract) that never runs at all. Those used to be `idle`, a second grey
  // that looked identical to this one — and the dimming has always actually meant this.
  off: { label: "off", color: "var(--graph-health-off)", pulse: false },
};
/**
 * The node's bottom-right STATE WORD (#3957) — axis 2's one-word slot.
 *
 * Precedence: a user-deactivated node reads `off` (that wins over any live status, #3239); a node whose
 * OWN health is degraded reads its health word (`warning`/`error`); otherwise its activity word.
 *
 * It deliberately does NOT return the node's `reason`. It used to: #2541 swapped the reason in "so the
 * user sees WHY the dot changed", which worked while reasons were short fault titles. They aren't — 
 * `applyStallHealth` appends a duration and #3931's `heldReason` names every unlanded upstream. The slot
 * is 108px, nowrap, ellipsis, so a sentence never overflowed, it TRUNCATED:
 * "waiting on 2 upstreams to land (domain-model…" rendered as "waiting on 2 upstre…", which reads as
 * garbage rather than a status. The reason is still on hover (`title`) and in the inspector's REASON
 * tile, both of which can actually display it.
 *
 * `rollupHealth` decides `off` (the deactivation is a rollup concern); `health` decides degraded (a node
 * must not read `warning` because a DEPENDENCY is degraded). Pure.
 */
export function nodeStateWord(n: { health: GHealth; rollupHealth?: GHealth; activity: GActivity }): string {
  // #4034 — no `off` WORD. A deactivated node is already dimmed in place (`offOpacity`, #3239) and
  // that IS the signal; spending the one word slot on it meant a node that was off AND complete read
  // "off" and lost the more useful fact. The dimming carries deactivation, the word carries what the
  // node IS.
  if (n.health === "warning" || n.health === "error") return HEALTH_META[n.health].label;
  return ACTIVITY_META[n.activity].label;
}

/** Axis 2 — ACTIVITY → the bottom-right lifecycle word (#2541). Colour is the health axis's job; this
 *  is just the label + whether it animates (a live app / building fleet reads as active). */
export const ACTIVITY_META: Record<GActivity, { label: string; pulse: boolean }> = {
  idle: { label: "idle", pulse: false },
  planning: { label: "planning", pulse: false },
  building: { label: "building", pulse: true },
  waiting: { label: "waiting", pulse: false },
  review: { label: "in review", pulse: false },
  live: { label: "live", pulse: true },
  // #4027 — the worker FINISHED. On the lifecycle axis, not health: health is the perpendicular
  // axis and already means something else, and "finished" is a lifecycle fact.
  //
  // Never pulses, deliberately — that completes the vocabulary: building BREATHES (#4015),
  // attention RINGS (#4005), complete is STILL. Motion means "look at this"; a finished worker is
  // the one state with nothing to do about it.
  complete: { label: "complete", pulse: false },
};
/** Project-network (L0) edge kind → label · colour · dash · line width · the relationship "surface"
 *  blurb (#2561 relabel). The relationships a user draws between PROJECTS — a build/runtime **dependency**,
 *  a **data flow** (one project consumes another's data — connectors/pipelines/migration), or an async
 *  **event stream** — NOT the microservice "API contract" framing this replaced. (The internal key `api`
 *  is kept for data/persist stability; only the user-facing label reads "depends on".) Fleet-drill (L1)
 *  edges speak the Org archetype grammar instead — see `glanceFleet`. */
export const EDGE_META: Record<GEdgeKind, { label: string; color: string; dash: string; w: number; surface: string }> = {
  api: { label: "depends on", color: "var(--graph-edge-api)", dash: "", w: 1.8, surface: "build & runtime dependency" },
  data: { label: "data flow", color: "var(--graph-edge-data)", dash: "", w: 1.8, surface: "consumes a data feed · schema-locked" },
  events: { label: "event stream", color: "var(--graph-edge-events)", dash: "6 5", w: 1.7, surface: "async messages · at-least-once" },
  // The kit-consumer dimension (#2571): a project CONSUMES a shared `bsc ui` kit — a design-system
  // dependency drawn to the shared kit node. Dashed cyan so it reads apart from the project edges.
  "uses-kit": { label: "uses kit", color: KIT_COLOR, dash: "4 4", w: 1.6, surface: "consumes a shared bsc ui kit · design-system dependency" },
  // The generalized cross-graph LIBRARY dimension (#3119, epic #3114): a project/page REQUIRES a node in
  // ANOTHER graph — an algorithm or a sound cue. Dashed like `uses-kit` so it reads as a library
  // dependency; the canvas tints each edge by the TARGET node's graph colour (LIBRARY_META), so this
  // static `color` is only a neutral fallback (e.g. the legend swatch).
  // The CRATE-DEPENDENCY dimension (`epic-command-surfaces-are-nodes`): one workspace crate depends on
  // another, read from its Cargo.toml. Deliberately NOT `api`, whose label is also "depends on" but
  // which is the PROJECT-network dimension — mixing them would put a cargo edge in the same band as a
  // project-to-project contract. Deliberately not `requires` either: that is project-to-library.
  // This is the edge that makes a surface node useful, because it is what says touching `bsc-util`
  // reaches most of the workspace.
  "depends-on": { label: "cargo dep", color: SURFACE_COLOR, dash: "4 4", w: 1.6, surface: "a cargo dependency between workspace crates \u00b7 touching the target rebuilds this one" },
  "uses-integration": { label: "integrates with", color: INTEGRATION_COLOR, dash: "5 3", w: 1.6, surface: "a project declared at Discovery that it integrates with this system \u00b7 the Integrator builds the connector" },
  requires: { label: "requires", color: "var(--fg-muted)", dash: "4 4", w: 1.6, surface: "requires a shared library node (algorithm / sound) · cross-graph dependency" },
  // The PROVENANCE dimension (#glance-architect-band): the architect session that created this project.
  // Dashed amber, matching ARCHITECT_META, so the tier that CREATES a project reads apart from the
  // dependencies it consumes.
  // #architects-own-projects: OWNERSHIP, not provenance. It was `created-by`/"created by", which stopped
  // being true the moment a project could be REASSIGNED — an edge that can move cannot claim to record
  // who created the thing. The surface names the command because there is no picker anywhere: `bsc` is
  // the only surface that sets this, so the graph is where a user has to learn the verb exists.
  "owned-by": { label: "architect", color: ARCHITECT_COLOR, dash: "4 4", w: 1.6, surface: "this project's architect · reassign with `bsc project architect set <key> <persona>`" },
  // A STREAM up to the FEATURE it belongs to (`a-feature-is-a-node`). Its own kind rather than
  // `owned-by`, which already means "this project's architect" — reusing it would put two unrelated
  // relationships behind one label and one colour.
  "belongs-to": { label: "belongs to", color: FEATURE_COLOR, dash: "", w: 1.4, surface: "the feature this stream is a lane of · move it with `bsc plan fleet stream feature <id> <slug>`" },
  // The SYSTEM-SESSION dimension (#glance-reads-left-to-right-sessions-to-libraries): the architect is
  // SERVED BY the app-owned studio sessions that produce the material its projects are built from.
  // Dashed slate, matching SESSION_META, and drawn architect→session so the session sits one layer
  // LEFT — the far upstream of the left→right funnel.
  "served-by": { label: "served by", color: SESSION_COLOR, dash: "4 4", w: 1.6, surface: "served by an app-owned studio session · produces kits / algorithms / sounds / connectors" },
  // The CRATE→VERB dimension (`a-crate-node-drills-into-its-verbs`) — the second layer: what one crate
  // actually lets you DO. Its own kind rather than `served-by`, whose meaning is already taken ("served
  // by an app-owned studio session"); reusing it would be exactly the collision `depends-on` exists to
  // avoid, one dimension over.
  // The VERB→NOUN dimension (`the-noun-reads-left-and-its-verbs-right`) — the second layer.
  //
  // DIRECTION IS THE LAYOUT, not a detail. `layoutProjectNetwork` hands `layerDag` the edges REVERSED
  // ("the dependency `to` must sit at a LOWER layer") and lays layers out left→right, so whatever an
  // edge points AT ends up on the LEFT. Drawn `noun → verb` the verbs landed left of their own noun,
  // which is backwards for a left-to-right reader. So the edge runs verb → noun, and the kind is named
  // for that direction rather than against it: `sessions` is a verb OF `logs`.
  "verb-of": { label: "verb of", color: SESSION_COLOR, dash: "", w: 1.4, surface: "a bsc verb this noun answers" },
  // The external MCP-CONTRACT dimension (#3786): a project CONTRACTS WITH a scoped MCP server — a wire
  // contract to an external tool/data server, drawn to the shared mcp node. Tight-dotted amber so it reads
  // apart from the kit/library edges.
  "uses-mcp": { label: "contracts with", color: MCP_COLOR, dash: "2 3", w: 1.6, surface: "contracts with a scoped external MCP server · a wire contract (Phase 1 inter-app contracts)" },
  // The external SERVICE-CONTRACT dimension (#3786 Phase 2): a project CONTRACTS WITH a third-party
  // service its planner declared — a wire contract to an external endpoint, drawn to the shared service
  // node. Tight-dotted indigo so it reads apart from the mcp + kit/library edges.
  "uses-service": { label: "contracts with", color: SERVICE_COLOR, dash: "2 3", w: 1.6, surface: "contracts with an external service · a planner-declared wire contract (Phase 2 inter-app contracts)" },
};

// Node box + spacing in world (design) coordinates.
export const NW = 186, NH = 66;
/** Node spacing in world coordinates. EXPORTED because a post-layout pass has to space nodes the same
 *  way the layout did — `studioProject`'s director/session split re-places nodes inside a tier, and a
 *  second copy of these numbers would drift the moment either is tuned. */
export const COLGAP = 252, ROWGAP = 102;

// The fenced LIBRARY band, RIGHT of the projects (#3007, generalized #3119; reoriented by
// #glance-reads-left-to-right-sessions-to-libraries). Band nodes (UI kits + algorithms + sounds + MCP
// servers + external services) are LIFTED out of the project dependency DAG into a single COLUMN here, so
// they read as a separate library dimension instead of an intermixed project column.
//
// It used to be a horizontal row across the TOP, which meant the graph was drawn on two axes at once:
// the funnel ran left→right (sessions → architect → projects) while the thing those projects consume sat
// above them. One axis reads as one pipeline, so the band moved to the end of the line.
const BAND_FENCE_PAD = 40;  // clearance from the projects' right edge out to the fence divider
/** Padding from a repo band's edge to the nearest card inside it. */
const REPO_BAND_PAD = 38;
/** Clear space between two repo bands, so the division reads without needing the divider line. */
const REPO_BAND_GUTTER = 54;
/** How many nodes one DEPENDENCY LAYER stacks before it wraps into another sub-column.
 *
 *  This is what bounds a band's HEIGHT, and it is the whole reason the grouping is usable. A fleet's
 *  layers are extremely lopsided — measured on this project, base-studio-code's 30 streams fall into 5
 *  layers of which ONE holds 16, and mobile-studio-code's 20 fall into 4 of which one holds 10. A layer
 *  laid out as a single column is therefore as tall as its widest layer, not as tall as its depth: 16
 *  rows ≈ 1630px for one band, ~2900px for the pair, which is what made the drill unreadable. */
const LAYER_WRAP = 6;
/** Horizontal step between the wrapped sub-columns INSIDE one layer. */
const SUBCOL_DX = NW + 40;
/** Clear space between one layer's last sub-column and the next layer's first — deliberately wider than
 *  {@link SUBCOL_DX}'s own inter-card gap, so a layer boundary still reads as a boundary once a layer
 *  is more than one column wide. */
const LAYER_GAP = 96;

/**
 * Stack a fleet drill's nodes into ONE HORIZONTAL BAND PER REPOSITORY, in place, and return the bands.
 *
 * WHY HORIZONTAL BANDS, SIDE BY SIDE WITH THE TIER. The layout engine lays dependency out LEFT→RIGHT,
 * so a band per repo keeps that axis intact — a chain still reads across, it just reads across inside
 * its repo. Vertical lanes would have forced every chain to wrap inside its lane and fought the layering
 * the DAG exists to show.
 *
 * The bands start to the RIGHT of everything ungrouped rather than below it. Stacking them underneath
 * was the first attempt and it read wrongly: the architect and its director/system tier are the
 * project's STRUCTURE, and putting the repos beneath them implied the repos hang off the tier the way a
 * debug session hangs off its spawner. Beside it, the two read as what they are — who is working, and
 * the codebases they work in.
 *
 * WHAT IS NOT BANDED: a node with no `repo` — the architect, the peer directors, the system sessions,
 * the debug sessions. They are project-scoped, not repo-scoped, and claiming otherwise would be an
 * invented fact. They keep the positions they already have, including the tier split a refiner may just
 * have applied.
 *
 * FEWER THAN TWO REPOS ⇒ NO BANDS. One band around everything states nothing the title bar does not
 * already say, and this is also what keeps the L0 project network untouched: its nodes are projects and
 * carry no repo at all.
 *
 * EACH BAND IS RE-PACKED, not merely translated, and that is a deliberate reversal of the first
 * version. Preserving the engine's own positions kept a band as tall as its WIDEST LAYER — see
 * {@link LAYER_WRAP} for the measurements — which made the drill scroll for thousands of pixels. Layer
 * ORDER is what carries the dependency meaning here, and it survives: layers still run left→right. Only
 * the within-layer stacking changes, wrapping into sub-columns instead of one tall column.
 *
 * Finally the whole stack is CENTRED on the director, so the workers sit level with the tier that runs
 * them instead of hanging off its top corner.
 *
 * Mutates `nodes`' x/y (the caller owns them and edge geometry has not run yet); returns the zones.
 */
export function bandNodesByRepo(nodes: GNode[]): RepoBand[] {
  // FIRST-APPEARANCE order, not alphabetical: the plan's own stream order is meaningful (it is roughly
  // build order), and sorting by name would shuffle it for no reason a reader could see.
  const repos: string[] = [];
  for (const n of nodes) if (n.repo && !repos.includes(n.repo)) repos.push(n.repo);
  if (repos.length < 2) return [];

  const unbanded = nodes.filter((n) => !n.repo);
  // The fence clears the RIGHTMOST ungrouped node — the architect, since the tier hangs off it and so
  // lays out to its left. With nothing ungrouped (an ordinary project's drill, where every node is a
  // stream) there is nothing to clear and the bands keep the engine's own left edge.
  const fenceX = unbanded.length
    ? Math.max(...unbanded.map((n) => n.x)) + NW + REPO_BAND_GUTTER
    : Math.min(...nodes.map((n) => n.x));
  // The graph's own top edge — the line the finished layout is slid back down to, so the centring
  // below can move things up freely without any of it landing off-canvas.
  const topEdge = Math.min(...nodes.map((n) => n.y));
  let cursor = topEdge;

  const bands: RepoBand[] = [];
  for (const repo of repos) {
    const mine = nodes.filter((n) => n.repo === repo);
    // Layer by layer, left→right; each layer wraps at LAYER_WRAP rows into as many sub-columns as it
    // needs, and the next layer starts clear of the widest of them.
    let x = fenceX, bottom = cursor;
    for (const layer of [...new Set(mine.map((n) => n.layer))].sort((a, b) => a - b)) {
      const inLayer = mine.filter((n) => n.layer === layer);
      inLayer.forEach((n, i) => {
        n.x = x + Math.floor(i / LAYER_WRAP) * SUBCOL_DX;
        n.y = cursor + (i % LAYER_WRAP) * ROWGAP;
        bottom = Math.max(bottom, n.y + NH);
      });
      x += Math.ceil(inLayer.length / LAYER_WRAP) * SUBCOL_DX + LAYER_GAP;
    }
    bands.push({
      repo, label: repo.split("/").pop() || repo,
      x0: fenceX - REPO_BAND_PAD, y0: cursor - REPO_BAND_PAD, y1: bottom + REPO_BAND_PAD,
    });
    cursor = bottom + REPO_BAND_PAD + REPO_BAND_GUTTER;
  }

  // CENTRE THE STACK ON THE DIRECTOR. The bands are built from the graph's top edge because that is the
  // only reference available while packing; the director's row is the one a reader actually relates them
  // to. Without this the workers hang off the tier's top corner and the taller the fleet, the more
  // lopsided it reads.
  const anchor = unbanded.find((n) => n.id === "director")
    ?? (unbanded.length ? unbanded[Math.floor(unbanded.length / 2)] : undefined);
  if (anchor && bands.length) {
    const shift = anchor.y + NH / 2 - (bands[0].y0 + bands[bands.length - 1].y1) / 2;
    for (const n of nodes) if (n.repo) n.y += shift;
    for (const b of bands) { b.y0 += shift; b.y1 += shift; }

    // THEN SLIDE THE WHOLE GRAPH BACK ONTO THE CANVAS, rather than clamping the stack.
    //
    // The fleet is normally TALLER than the tier beside it, so centring it on the director means moving
    // it UP past the top edge — `worldH` is measured from the nodes, so a negative y is unreachable, not
    // merely ugly. Clamping the stack there was the first attempt and it silently un-did the centring
    // for exactly the graphs that needed it (measured: 149px out on a four-worker fleet).
    //
    // Moving EVERYTHING down instead preserves the alignment — a rigid translation cannot change the
    // relationship it just established — and the tier simply sits lower, which is the honest picture: it
    // is the smaller of the two things being centred on each other.
    const floor = Math.min(...nodes.map((n) => n.y), ...bands.map((b) => b.y0));
    if (floor < topEdge) {
      const drop = topEdge - floor;
      for (const n of nodes) n.y += drop;
      for (const b of bands) { b.y0 += drop; b.y1 += drop; }
    }
  }
  return bands;
}
const BAND_CARD_GAP = 34;   // clearance from the fence divider across to the band cards' left edge

/** Lay out `count` band cards as a vertical COLUMN — the transpose of A's shared `layoutBand`, which
 *  only does rows. Evenly spaced and centred over the project span [`spanY0`, `spanY1`], the step capped
 *  at `maxStep` so a couple of nodes cluster in the middle instead of stretching the full height.
 *
 *  Deliberately local rather than a change to `layoutBand`: that helper is shared with the Design Studio
 *  composition swimlanes, which are genuinely horizontal, so generalizing it to both axes would make
 *  every caller pass an orientation to get what it already had. */
function layoutBandColumn(count: number, spanY0: number, spanY1: number, x: number, maxStep: number): { x: number; y: number }[] {
  if (count <= 0) return [];
  const span = Math.max(0, spanY1 - spanY0);
  const step = count > 1 ? Math.min(span / (count - 1), maxStep) : 0;
  const colH = step * (count - 1);
  const startY = spanY0 + (span - colH) / 2;
  return Array.from({ length: count }, (_, i) => ({ x, y: startY + i * step }));
}

/** Bezier path + arrowhead between two node boxes (F depends on T). Cycle back-edges bow to separate the
 *  two directions. Ported from the spec's edgeGeom.
 *
 *  EVERY edge now uses side-port routing (#glance-reads-left-to-right-sessions-to-libraries). It used to
 *  branch on `kind`: a library edge ran VERTICALLY into the top band, where side ports would have met the
 *  wrong faces, so it fell back to the perimeter-anchor router. With the band moved to a column RIGHT of
 *  the projects, every dimension — sessions, architect, projects, libraries — lies on the same left→right
 *  axis, so there is no longer a second orientation to special-case. `kind` is kept in the signature
 *  because callers pass it and the legend/labels still key off it. */
export function edgeGeom(F: { x: number; y: number; id: string }, T: { x: number; y: number; id: string }, isCycle: boolean, _kind?: GEdgeKind): { d: string; arrow: string } {
  // The shared graph line-type (#2222) with SIDE-PORT routing (#2226) — Glance is a layered left→right
  // DAG, so edges leave the right edge / enter the left at the vertical middle for a clean columnar flow
  // (the perimeter-anchor router read messy here). Cycle back-edges bow apart (deterministic sign by id
  // order) so the two directions of a↔b don't overlap.
  const bow = isCycle ? (F.id < T.id ? -46 : 46) : 0;
  const { d, arrow } = graphEdge({ x: F.x, y: F.y, w: NW, h: NH }, { x: T.x, y: T.y, w: NW, h: NH }, { bow, routing: "ports" as const });
  return { d, arrow };
}

/** The nodes + edges to KEEP lit when something is focused (hovered/selected), so the rest dims. Null
 *  means "nothing focused — everything lit." A node lights itself + its neighbors + connecting edges;
 *  an edge lights its two endpoints; `showCycle` lights every cycle edge + its nodes. Pure. */
export function focusSets(
  model: GraphModel,
  activeNodeId: string | null,
  activeEdgeId: string | null,
  showCycle: boolean,
): { nodes: Set<string>; edges: Set<string> } | null {
  if (activeNodeId) {
    const sp = neighborSpotlight(model.edges, activeNodeId);
    return { nodes: sp.litNodes, edges: sp.litEdges };
  }
  if (activeEdgeId) {
    const e = model.edges.find((x) => x.id === activeEdgeId);
    return e ? { nodes: new Set([e.from, e.to]), edges: new Set([e.id]) } : null;
  }
  if (showCycle) {
    const nodes = new Set<string>(), edges = new Set<string>();
    for (const e of model.edges) if (e.isCycle) { edges.add(e.id); nodes.add(e.from); nodes.add(e.to); }
    return { nodes, edges };
  }
  return null;
}

/**
 * Roll HEALTH up the dependency chain (#2541): each node's effective health is the WORST of its own
 * health and every node it (transitively) depends on — so a foundational service's error surfaces on
 * everything downstream that depends on it. Only `warning`/`error` (rank ≥ 1) propagate; `idle`/`healthy`
 * never override the dependent's own resting state. Cycle-safe (a per-start visited set). Pure.
 *
 * Returns, per node id, the rolled-up `health` and whether it is `inherited` (worse than the node's own
 * health — i.e. lit only because of a dependency, so the dot renders muted, not as the origin).
 */
export function rollUpHealth(
  nodes: { id: string; health: GHealth }[],
  edges: { from: string; to: string }[],
): Map<string, { health: GHealth; inherited: boolean }> {
  const own = new Map(nodes.map((n) => [n.id, n.health]));
  const deps = new Map<string, string[]>(nodes.map((n) => [n.id, []]));
  for (const e of edges) deps.get(e.from)?.push(e.to); // `from depends on to`
  const worstFrom = (start: string): GHealth => {
    // A user-deactivated node stays `off` (#3239): the deliberate mute wins over any downstream error,
    // so an off node never lights up because of a dependency. (`off` is rank 0, so it also never
    // propagates OUT — a node depending on an off node is unaffected.)
    if (own.get(start) === "off") return "off";
    let worst: GHealth = own.get(start) ?? "off";
    const seen = new Set<string>([start]);
    const stack = [...(deps.get(start) ?? [])];
    while (stack.length) {
      const id = stack.pop()!;
      if (seen.has(id)) continue;
      seen.add(id);
      const h: GHealth = own.get(id) ?? "off";   // #4042: no own health ⇒ nothing live behind it
      if (HEALTH_RANK[h] > HEALTH_RANK[worst]) worst = h;
      for (const d of deps.get(id) ?? []) stack.push(d);
    }
    return worst;
  };
  const out = new Map<string, { health: GHealth; inherited: boolean }>();
  for (const n of nodes) {
    const eff = worstFrom(n.id);
    out.set(n.id, { health: eff, inherited: HEALTH_RANK[eff] > HEALTH_RANK[own.get(n.id) ?? "off"] });
  }
  return out;
}

/** Lay out the PROJECT network (kits excluded, #3007) with the layered left→right DAG engine — a plain
 *  GRID when there are no project dependency edges, else longest-path layering + barycenter ordering.
 *  Mutates each project node's `layer`/`x`/`y` in place. `byId` indexes ALL nodes; `cycleEdge` is the set
 *  of mutual-pair edge ids to exclude from layering. This is the pre-#3007 `buildGraph` body verbatim,
 *  scoped to `projNodes`/`projEdges` (so a project-only graph is byte-identical to before). */
function layoutProjectNetwork(projNodes: GNode[], projEdges: GEdge[], byId: Record<string, GNode>, cycleEdge: ReadonlySet<string>): void {
  // No dependency edges (real projects before a cross-project relationship model exists): a plain GRID so
  // the cards read as a network of peers instead of stacking in one column. Skip the layering.
  if (projEdges.length === 0) {
    const cols = Math.max(1, Math.round(Math.sqrt(projNodes.length)));
    projNodes.forEach((n, i) => { n.layer = 0; n.x = 70 + (i % cols) * COLGAP; n.y = 70 + Math.floor(i / cols) * ROWGAP; });
    return;
  }

  // Longest-path layering via the shared layerer (#2214). Glance is a DEPENDS-ON DAG (from depends on
  // to → the dependency `to` must sit at a LOWER layer), so we hand `layerDag` the edges REVERSED — its
  // "from → deeper" convention then puts each dependency below its dependent. Cycle (mutual-pair) edges
  // are excluded so the loop can't diverge.
  const reversed = projEdges.map((e) => ({ id: e.id, from: e.to, to: e.from }));
  const layer = layerDag(projNodes.map((n) => n.id), reversed, cycleEdge);
  projNodes.forEach((n) => (n.layer = layer[n.id]));

  // Crossing reduction via the shared barycenter orderer (#2418) with glance's tunables: every edge
  // endpoint pulls (both directions, cycle edges included), 6 snapshot sweeps.
  const nb = new Map<string, string[]>(projNodes.map((n) => [n.id, []]));
  projEdges.forEach((e) => { nb.get(e.from)!.push(e.to); nb.get(e.to)!.push(e.from); });
  const order = orderLayers(projNodes.map((n) => n.id), (id) => layer[id], (id) => nb.get(id)!, { passes: 6, sweep: "snapshot" });

  const maxCount = Math.max(1, ...[...order.values()].map((a) => a.length));
  const Cy = 70 + (maxCount - 1) * ROWGAP / 2;
  for (const [L, arr] of order) {
    arr.forEach((id, i) => {
      byId[id].x = 70 + L * COLGAP;
      byId[id].y = Cy + (i - (arr.length - 1) / 2) * ROWGAP;
    });
  }
}

/** Caller-supplied options for {@link buildGraph}. */
export interface BuildGraphOptions {
  /** A REFINEMENT of the laid-out positions, applied after the layout engine and BEFORE edge geometry.
   *
   *  It has to run inside `buildGraph` rather than on the returned model, because every edge's `d` path
   *  and arrow are computed FROM the node positions here — moving a node afterwards leaves its edges
   *  pointing at where it used to be. That is the whole reason this hook exists instead of a
   *  post-process.
   *
   *  Receives the laid-out nodes AND the edges — a refiner that groups children under their parent needs
   *  to know which node points at which, and that only exists on the edges. Returns the set to use; only
   *  `x`/`y` are read back, so a refiner cannot change the graph's shape. Used by the studio drill to split its director/session tier
   *  (`splitDirectorSessionTiers`). */
  refineLayout?: (nodes: GNode[], edges: GEdge[]) => GNode[];
}

/** Build the laid-out, cycle-aware graph model from raw nodes + edges. Deterministic. */
export function buildGraph(rawNodes: GRawNode[], rawEdges: GRawEdge[], opts?: BuildGraphOptions): GraphModel {
  const nodes: GNode[] = rawNodes.map((n) => ({ ...n, slug: n.slug ?? n.id, layer: 0, x: 0, y: 0, rollupHealth: n.health, healthInherited: false }));
  const byId: Record<string, GNode> = {};
  nodes.forEach((n) => (byId[n.id] = n));

  const edges: GEdge[] = rawEdges
    .filter((e) => byId[e.from] && byId[e.to] && e.from !== e.to)
    .map((e, i) => ({ id: e.id ?? "e" + i, from: e.from, to: e.to, kind: e.kind, archetype: e.archetype, hard: e.kind !== "events", isCycle: false, d: "", arrow: "" }));

  // Cycle detection: mutual pairs (a→b AND b→a) — the shared graph-core primitive (#2217).
  const { pairs: cyclePairs, edgeIds: cycleEdge, nodeIds: cycleNodeIds } = mutualPairs(edges);
  edges.forEach((e) => { if (cycleEdge.has(e.id)) e.isCycle = true; });

  // Roll health up the dependency edges (#2541) — every node now carries its effective (rolled) health.
  // Band nodes (kits/algorithms/sounds AND mcp contracts, #3786) are always `idle` and never propagate, so
  // the `uses-kit` / `requires` / `uses-mcp` edges have no effect here (#3007/#3119/#3786).
  const rolled = rollUpHealth(nodes, edges);
  nodes.forEach((n) => { const r = rolled.get(n.id)!; n.rollupHealth = r.health; n.healthInherited = r.inherited; });

  // #3007 (generalized #3119 → external contracts #3786) — LIFT every non-project BAND node (UI kits
  // AND/OR algorithms/sounds AND/OR mcp contracts) out of the dependency DAG into their own fenced band
  // across the top, so they read as a separate dimension, not an intermixed project column. The PROJECT
  // network lays out with ONLY the project nodes + project edges (the existing engine, unchanged); the band
  // nodes then sit in a single row above it and every project node shifts down to clear the band.
  const bandNodes = nodes.filter(isBandNode);
  const projNodes = nodes.filter((n) => !isBandNode(n));
  const projEdges = edges.filter((e) => !isBandEdge(e.kind));

  layoutProjectNetwork(projNodes, projEdges, byId, cycleEdge);

  // The refinement seam: positions are final for the project network here, and edge geometry has not
  // been computed yet. Only x/y are taken back, so a refiner can reposition but never restructure.
  if (opts?.refineLayout) {
    for (const r of opts.refineLayout(projNodes, projEdges)) {
      const n = byId[r.id];
      if (n) { n.x = r.x; n.y = r.y; }
    }
  }

  // REPOSITORY GROUPS, after the refiner so the tier split is already settled and the bands can start
  // below it, and before edge geometry so the moved endpoints are the ones the edges are drawn from.
  const repoBands = bandNodesByRepo(projNodes);

  let bandZone: { x0: number; x1: number } | undefined;
  if (bandNodes.length > 0) {
    // A single library COLUMN past the rightmost project, evenly spaced and centred over the project's
    // vertical span, the step capped at one row gap so a couple of nodes cluster in the middle instead of
    // stretching the full height. `layer = -1` marks them as band nodes (outside the project layering).
    //
    // Unlike the old top band, nothing shifts: the column occupies space the project network never used,
    // so the projects keep the exact positions the layout engine gave them.
    const projMaxX = projNodes.length ? Math.max(...projNodes.map((n) => n.x)) : 70;
    const projMinY = projNodes.length ? Math.min(...projNodes.map((n) => n.y)) : 70;
    const projMaxY = projNodes.length ? Math.max(...projNodes.map((n) => n.y)) : 70;
    const fenceX = projMaxX + NW + BAND_FENCE_PAD;
    const cardX = fenceX + BAND_CARD_GAP;
    const positions = layoutBandColumn(bandNodes.length, projMinY, projMaxY, cardX, ROWGAP);
    bandNodes.forEach((k, i) => { k.layer = -1; k.x = positions[i].x; k.y = positions[i].y; });

    // The fence sits a gap to the LEFT of the band cards; the zone runs from there out past their right
    // edge, so the canvas has a rect to wash and a divider line to draw.
    bandZone = { x0: fenceX, x1: cardX + NW + BAND_FENCE_PAD };
  }

  let maxX = 0, maxY = 0;
  nodes.forEach((n) => { maxX = Math.max(maxX, n.x); maxY = Math.max(maxY, n.y); });
  const worldW = maxX + NW + 80, worldH = maxY + NH + 90;

  // Edge geometry LAST — after both the project layout and the library-band shift — so every endpoint is
  // final. `e.kind` routes LIBRARY edges (`uses-kit`/`requires`) vertically (perimeter-anchor); project
  // edges keep side ports.
  edges.forEach((e) => Object.assign(e, edgeGeom(byId[e.from], byId[e.to], e.isCycle, e.kind)));

  return { nodes, edges, cyclePairs, cycleNodeIds, worldW, worldH, bandZone, repoBands: repoBands.length ? repoBands : undefined };
}

